// Gerado a partir do material de formação. Não editar à mão.
import type { CapituloDoLivro, QuestaoDaAvaliacao } from "./tipos";

export const capitulos: CapituloDoLivro[] = [{"id":"c1","titulo":"O papel da escola na proteção","html":"<p>A escola é o lugar onde a criança e o adolescente passam mais tempo fora de casa, diante de adultos que os conhecem. Por isso, muitas situações de violência são percebidas primeiro pelo professor.</p><p>O professor não precisa ter certeza nem provar nada. O papel dele é perceber, acolher e comunicar. A investigação e a proteção cabem aos órgãos competentes.</p><h3>Ao final, você será capaz de</h3><ul><li>Reconhecer sinais que pedem atenção.</li><li>Acolher o relato de um aluno sem causar novo sofrimento.</li><li>Comunicar a suspeita pelo caminho certo.</li><li>Identificar o bullying e agir com a vítima, com o autor e com a turma.</li><li>Conhecer os seus deveres legais.</li></ul><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Passo</th><th>O que significa</th></tr></thead><tbody><tr><td>Perceber</td><td>Notar mudanças e sinais, sem tirar conclusões.</td></tr><tr><td>Acolher</td><td>Ouvir com calma, acreditar e não julgar.</td></tr><tr><td>Comunicar</td><td>Levar à direção no mesmo dia. A direção comunica ao Conselho Tutelar.</td></tr><tr><td>Acompanhar</td><td>Manter o vínculo e a rotina do aluno na escola.</td></tr></tbody></table></div><div class=\"nota alerta\"><b>Dever legal</b><br/>O Estatuto da Criança e do Adolescente obriga a comunicar ao Conselho Tutelar a suspeita ou a confirmação de maus-tratos (art. 13). O professor ou o responsável pela escola que deixa de comunicar comete infração (art. 245). A Lei nº 14.344/2022 reforça o dever de comunicar a violência doméstica e familiar contra criança e adolescente.</div>"},{"id":"c2","titulo":"Formas de violência","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Forma</th><th>O que é</th></tr></thead><tbody><tr><td>Física</td><td>Uso da força que causa dor ou lesão.</td></tr><tr><td>Psicológica</td><td>Humilhação, ameaça, rejeição, isolamento ou exposição a violência.</td></tr><tr><td>Sexual</td><td>Qualquer ato ou exposição de natureza sexual envolvendo criança ou adolescente, com ou sem contato físico, inclusive pela internet.</td></tr><tr><td>Negligência</td><td>Falta de cuidados básicos de alimentação, saúde, higiene, proteção e frequência escolar.</td></tr><tr><td>Exploração</td><td>Trabalho infantil ou uso da criança para obter vantagem.</td></tr><tr><td>Institucional</td><td>Violência praticada por quem deveria proteger, inclusive na escola.</td></tr></tbody></table></div><div class=\"nota\"><b>Onde acontece</b><br/>A maior parte das violências contra crianças ocorre em ambientes conhecidos e é praticada por pessoas próximas. Por isso a criança muitas vezes demora a contar e pode proteger quem a agride.</div>"},{"id":"c3","titulo":"Sinais que pedem atenção","html":"<p>Nenhum sinal isolado confirma uma violência. Vários sinais juntos, ou uma mudança brusca, pedem comunicação à direção.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Área</th><th>O que pode aparecer</th></tr></thead><tbody><tr><td>Corpo</td><td>Marcas ou machucados frequentes, sem explicação ou com explicação que não combina. Dor ou desconforto ao sentar ou andar. Descuido persistente com higiene e saúde. Fome constante.</td></tr><tr><td>Comportamento</td><td>Mudança brusca: o aluno calmo fica agressivo, o falante se cala. Medo de voltar para casa ou de uma pessoa específica. Regressão a comportamentos de idade menor. Fugas, faltas e sono em sala.</td></tr><tr><td>Emoções</td><td>Tristeza persistente, choro, ansiedade, vergonha excessiva, culpa. Machucar a si mesmo.</td></tr><tr><td>Convivência</td><td>Isolamento, desconfiança de adultos, recusa de contato físico comum ou busca exagerada de afeto.</td></tr><tr><td>Conhecimento e falas</td><td>Conhecimento ou brincadeiras de teor sexual incompatíveis com a idade. Desenhos e textos com conteúdo de violência. Segredos com um adulto.</td></tr><tr><td>Aprendizagem</td><td>Queda repentina no rendimento e na atenção.</td></tr><tr><td>Internet</td><td>Uso escondido do celular, presentes ou dinheiro de desconhecidos, contato com adultos pela rede.</td></tr></tbody></table></div><div class=\"nota alerta\"><b>Em caso de dúvida, comunique</b><br/>A escola comunica a suspeita. Quem avalia e confirma são os serviços especializados. Esperar a certeza pode manter a criança em risco.</div>"},{"id":"c4","titulo":"Quando o aluno conta","html":"<figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Ouvir</b><small>em local reservado, com calma</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Acreditar</b><small>sem demonstrar espanto</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Não perguntar detalhes</b><small>o aluno fala o que quiser</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Explicar</b><small>que vai buscar ajuda</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Comunicar</b><small>à direção, no mesmo dia</small></div></div><figcaption>Figura. Como agir diante do relato espontâneo de um aluno.</figcaption></figure><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Faça</th><th>Não faça</th></tr></thead><tbody><tr><td>Ouça sem interromper e agradeça a confiança.</td><td>Fazer perguntas sobre detalhes ou pedir que repita.</td></tr><tr><td>Diga que ele fez certo em contar e que a culpa não é dele.</td><td>Demonstrar choque, raiva ou dúvida.</td></tr><tr><td>Explique que vai pedir ajuda a quem pode protegê-lo.</td><td>Prometer segredo.</td></tr><tr><td>Anote, logo depois, o que ele disse, com as palavras dele.</td><td>Interpretar ou completar o relato.</td></tr><tr><td>Leve à direção no mesmo dia.</td><td>Procurar ou confrontar a pessoa apontada.</td></tr><tr><td>Mantenha a rotina e o carinho de sempre.</td><td>Comentar com colegas, com a turma ou em grupos de mensagens.</td></tr></tbody></table></div><div class=\"nota\"><b>Por que não perguntar detalhes</b><br/>A Lei nº 13.431/2017 prevê que a criança seja ouvida por profissional preparado, uma única vez sempre que possível. Fazer a criança repetir o relato a várias pessoas causa novo sofrimento e pode prejudicar a proteção.</div>"},{"id":"c5","titulo":"O caminho da comunicação","html":"<figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Professor</b><small>percebe ou recebe o relato</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Direção</b><small>recebe o registro no mesmo dia</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Conselho Tutelar</b><small>é comunicado pela escola</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Rede de proteção</b><small>saúde, assistência e Justiça atuam</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Escola</b><small>acompanha o aluno</small></div></div><figcaption>Figura. Da sala de aula à rede de proteção.</figcaption></figure><h3>O que registrar</h3><ul><li>Data, horário e local.</li><li>O que foi observado ou dito, com as palavras do aluno.</li><li>Quem estava presente.</li><li>A quem foi comunicado e quando.</li></ul><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Serviço</th><th>Quando acionar</th><th>Como</th></tr></thead><tbody><tr><td>Conselho Tutelar</td><td>Suspeita ou confirmação de violência, negligência ou violação de direitos de criança ou adolescente.</td><td>Comunicação pela direção da escola. É obrigatória.</td></tr><tr><td>Disque 100</td><td>Denúncia de violação de direitos humanos, inclusive anônima.</td><td>Telefone 100, todos os dias, 24 horas.</td></tr><tr><td>Polícia Militar</td><td>Risco imediato à vida ou crime em andamento.</td><td>Telefone 190.</td></tr><tr><td>SAMU</td><td>Pessoa ferida ou em emergência de saúde.</td><td>Telefone 192.</td></tr><tr><td>CRAS e CREAS</td><td>Família em vulnerabilidade ou com direitos violados.</td><td>Encaminhamento pela direção ou pelo Conselho Tutelar.</td></tr><tr><td>Unidade de saúde e CAPS</td><td>Sofrimento emocional, uso de substâncias ou suspeita de transtorno.</td><td>Encaminhamento pela escola, com a família.</td></tr><tr><td>Ministério Público e Defensoria Pública</td><td>Violação de direitos sem resposta dos demais serviços.</td><td>Pela Secretaria de Educação ou pela direção.</td></tr></tbody></table></div><div class=\"nota alerta\"><b>Se a suspeita recai sobre alguém da escola</b><br/>A comunicação é feita do mesmo modo, à direção ou, se necessário, diretamente à Secretaria ou ao Conselho Tutelar. O aluno é protegido e afastado do contato com a pessoa apontada.</div>"},{"id":"c6","titulo":"Bullying: o que é e o que não é","html":"<p>A Lei nº 13.185/2015 define a intimidação sistemática como todo ato de violência física ou psicológica, intencional e repetitivo, praticado sem motivação evidente, por um ou mais alunos contra outro, em uma relação de desequilíbrio de poder.</p><div class=\"tb\"><table class=\"larga\"><thead><tr><th>É bullying</th><th>Não é bullying</th></tr></thead><tbody><tr><td>Apelidos e xingamentos repetidos contra o mesmo aluno.</td><td>Uma discussão entre colegas com forças parecidas.</td></tr><tr><td>Exclusão combinada de um aluno do grupo.</td><td>Uma brincadeira em que todos se divertem.</td></tr><tr><td>Agressões, empurrões ou danos a pertences, de forma repetida.</td><td>Uma briga isolada, que deve ser tratada, mas tem outro nome.</td></tr><tr><td>Boatos, montagens e humilhações pela internet.</td><td>Uma crítica pontual a um trabalho.</td></tr></tbody></table></div><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Tipo</th><th>Exemplos</th></tr></thead><tbody><tr><td>Verbal</td><td>Insultar, apelidar, ameaçar.</td></tr><tr><td>Moral</td><td>Difamar, espalhar boatos.</td></tr><tr><td>Social</td><td>Isolar, excluir, ignorar.</td></tr><tr><td>Físico</td><td>Bater, empurrar, tomar pertences.</td></tr><tr><td>Material</td><td>Estragar ou esconder objetos.</td></tr><tr><td>Virtual</td><td>Humilhar, expor ou perseguir pela internet.</td></tr></tbody></table></div><div class=\"nota\"><b>O que diz a lei</b><br/>A Lei nº 13.185/2015 obriga as escolas a adotar medidas de conscientização, prevenção e combate. A Lei nº 14.811/2024 incluiu a intimidação sistemática e a intimidação sistemática virtual no Código Penal.</div>"},{"id":"c7","titulo":"Como identificar o bullying","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Quem</th><th>Sinais</th></tr></thead><tbody><tr><td>Quem sofre</td><td>Evita a escola ou certos lugares. Fica sozinho no recreio. Material estragado ou sumido. Tristeza, queda no rendimento, queixas de dor sem causa. Pede para mudar de lugar ou de turma.</td></tr><tr><td>Quem pratica</td><td>Busca plateia. Humilha para fazer rir. Tem dificuldade de aceitar regras e de se colocar no lugar do outro. Pode estar repetindo o que vive.</td></tr><tr><td>Quem assiste</td><td>Ri por medo de ser o próximo. Sabe o que acontece e não conta. É quem mais pode ajudar a interromper.</td></tr></tbody></table></div><h3>Onde observar</h3><ul><li>Recreio, corredores, banheiros, entrada e saída.</li><li>Formação de grupos nos trabalhos: quem sempre sobra.</li><li>Risadas e cochichos quando um aluno fala.</li><li>Grupos de mensagens da turma.</li></ul>"},{"id":"c8","titulo":"Como agir diante do bullying","html":"<ol class=\"passos\"><li>Interrompa a agressão na hora, com calma e firmeza.</li><li>Converse com a vítima em particular. Diga que a culpa não é dela e que a escola vai agir.</li><li>Converse com o autor em separado. Trate do comportamento, sem humilhar.</li><li>Comunique à coordenação, que chama os responsáveis de cada lado, em separado.</li><li>Trabalhe o tema com a turma, sem citar nomes.</li><li>Acompanhe nas semanas seguintes.</li></ol><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Faça</th><th>Não faça</th></tr></thead><tbody><tr><td>Levar a sério todo relato.</td><td>Dizer que é brincadeira ou que o aluno precisa se defender.</td></tr><tr><td>Proteger a vítima e mantê-la nas atividades.</td><td>Colocar vítima e autor frente a frente para \"resolver\".</td></tr><tr><td>Dar ao autor a chance de reparar.</td><td>Humilhar o autor diante da turma.</td></tr><tr><td>Envolver quem assiste.</td><td>Tratar como problema apenas dos dois alunos.</td></tr></tbody></table></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · o apelido que não parava</div><p><b>Situação.</b> Um aluno do 6º ano recebe o mesmo apelido todos os dias. A turma ri. Ele passa a faltar.</p><p><b>O que fazer.</b></p><ol><li>Interrompa quando ouvir o apelido, sem dar plateia ao autor.</li><li>Converse com o aluno em particular e registre.</li><li>Leve à coordenação, que conversa com os responsáveis.</li><li>Faça com a turma uma atividade sobre respeito e sobre o papel de quem assiste.</li><li>Observe o recreio e os grupos de trabalho nas semanas seguintes.</li></ol><p><b>Resultado esperado.</b> O apelido deixa de ter plateia, e o aluno volta a frequentar as aulas.</p></div>"},{"id":"c9","titulo":"Prevenção no dia a dia","html":"<ul class=\"chk\"><li><span></span>A turma construiu regras de convivência e as revê de tempos em tempos.</li><li><span></span>Há espaço regular para a turma conversar sobre como está a convivência.</li><li><span></span>Os alunos sabem a quem procurar e que serão ouvidos.</li><li><span></span>As atividades em grupo variam a formação, para ninguém sobrar sempre.</li><li><span></span>O professor circula no recreio e nos corredores.</li><li><span></span>O uso de celular e de grupos de mensagens é tema de conversa com a turma e com os responsáveis.</li></ul><div class=\"nota\"><b>Conversar sobre o corpo e os limites</b><br/>Ensinar, em linguagem adequada à idade, que o corpo é da criança, que ela pode dizer não e que deve contar a um adulto de confiança quando algo a incomoda é uma das formas mais eficazes de prevenção.</div>"},{"id":"c10","titulo":"O que a lei garante e o que ela exige da escola","html":"<p>A Constituição Federal (art. 227) determina que a família, a sociedade e o Estado protejam a criança e o adolescente com prioridade absoluta. A escola faz parte desse dever. Conhecer as leis ajuda o servidor a agir com segurança e a explicar à família por que a escola comunica.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Norma</th><th>O que diz</th><th>O que muda na escola</th></tr></thead><tbody><tr><td>Estatuto da Criança e do Adolescente (Lei 8.069/1990)</td><td>Proteção integral. Art. 13: suspeita ou confirmação de maus-tratos é comunicada ao Conselho Tutelar. Art. 56: dirigentes de escola comunicam maus-tratos, faltas reiteradas e evasão. Art. 245: deixar de comunicar é infração.</td><td>Comunicar não é escolha do servidor. É dever.</td></tr><tr><td>Lei 13.010/2014</td><td>Direito de ser educado sem castigo físico e sem tratamento cruel ou degradante.</td><td>Vale para a família e para todo adulto que cuida ou educa, inclusive na escola.</td></tr><tr><td>Lei 13.431/2017 e Decreto 9.603/2018</td><td>Cria o sistema de garantia de direitos da criança vítima ou testemunha de violência. Define a escuta especializada e o depoimento especial.</td><td>A escola acolhe o relato espontâneo e não interroga. Quem ouve em detalhe é profissional preparado.</td></tr><tr><td>Lei 13.185/2015</td><td>Programa de Combate à Intimidação Sistemática.</td><td>A escola deve prevenir, identificar e agir diante do bullying.</td></tr><tr><td>Lei 13.663/2018</td><td>Inclui na Lei de Diretrizes e Bases o dever de promover a cultura de paz e de combater todos os tipos de violência.</td><td>Prevenção faz parte do trabalho da escola, não é projeto opcional.</td></tr><tr><td>Lei 13.819/2019</td><td>Política de prevenção da automutilação e do suicídio.</td><td>A escola comunica ao Conselho Tutelar, em sigilo, os casos de violência autoprovocada.</td></tr><tr><td>Lei 14.344/2022</td><td>Mecanismos de proteção contra a violência doméstica e familiar.</td><td>Reforça o dever de comunicar e prevê medidas protetivas de urgência.</td></tr><tr><td>Lei 14.643/2023</td><td>Sistema nacional de acompanhamento e combate à violência nas escolas.</td><td>Estimula o registro e o acompanhamento dos casos pela rede.</td></tr><tr><td>Lei 14.811/2024</td><td>Torna crime o bullying e o cyberbullying e reforça a proteção em estabelecimentos educacionais.</td><td>Exige certidão de antecedentes criminais de quem trabalha com crianças, atualizada periodicamente.</td></tr></tbody></table></div><div class=\"nota\"><b>Comunicar não é denunciar a família</b><br/>A comunicação ao Conselho Tutelar é um pedido de proteção para o aluno. Ela não acusa ninguém. A apuração cabe aos órgãos competentes.</div>"},{"id":"c11","titulo":"Mitos que atrapalham a proteção","html":"<p>Algumas ideias muito repetidas fazem o adulto duvidar do que vê e adiar a comunicação. Conhecer os fatos ajuda a agir.</p><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Mito</th><th>O que se sabe</th></tr></thead><tbody><tr><td>\"Quem agride é um estranho.\"</td><td>Na maior parte dos casos, quem agride é alguém da família ou da convivência da criança.</td></tr><tr><td>\"Se fosse verdade, ele teria contado antes.\"</td><td>A criança demora a contar por medo, vergonha, culpa, ameaça ou afeto por quem a agride. A demora é comum.</td></tr><tr><td>\"Criança inventa essas coisas.\"</td><td>Relatos falsos são raros. É mais comum a criança negar o que aconteceu do que inventar.</td></tr><tr><td>\"Ele mudou a história, então mentiu.\"</td><td>Voltar atrás é frequente. Pode vir de pressão da família ou do medo das consequências.</td></tr><tr><td>\"Isso só acontece em família pobre.\"</td><td>A violência ocorre em todas as classes sociais. Em famílias com mais recursos, ela costuma ficar mais escondida.</td></tr><tr><td>\"Só meninas sofrem violência sexual.\"</td><td>Meninos também são vítimas e tendem a contar ainda menos.</td></tr><tr><td>\"Sem marca no corpo, não houve violência.\"</td><td>Muitas violências não deixam marca: a psicológica, a negligência e grande parte da violência sexual.</td></tr><tr><td>\"Preciso ter certeza para comunicar.\"</td><td>A lei pede comunicação diante da suspeita. Quem confirma é a rede de proteção.</td></tr><tr><td>\"Se eu comunicar, vou piorar a vida da criança.\"</td><td>O silêncio mantém a violência. A comunicação é o que abre o caminho da proteção.</td></tr><tr><td>\"Bullying é coisa de criança, sempre existiu.\"</td><td>A intimidação repetida causa sofrimento, faltas, queda no rendimento e adoecimento. Hoje é crime.</td></tr></tbody></table></div><div class=\"pratica\"><div class=\"tt\">Para praticar · o que eu já ouvi</div><div class=\"q\"><b>1.</b> Qual desses mitos você já ouviu na sua escola?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>2.</b> O que você responderia hoje a um colega que dissesse essa frase?<div class=\"ln\"></div><div class=\"ln\"></div></div></div>"},{"id":"c12","titulo":"Sinais em cada idade","html":"<p>Os sinais mudam com a idade. A criança menor mostra no corpo e na brincadeira. O adolescente mostra no afastamento, no risco e no silêncio. Em qualquer idade, o que mais importa é a mudança em relação ao que o aluno era.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Idade</th><th>O que pode aparecer</th><th>O que observar na escola</th></tr></thead><tbody><tr><td>6 a 8 anos</td><td>Volta a fazer xixi na roupa, chupar dedo ou falar como criança menor. Medo intenso de ficar só. Choro sem motivo aparente. Brincadeiras que repetem cenas de violência.</td><td>Desenhos, faz de conta, hora da saída e quem vem buscar.</td></tr><tr><td>9 a 11 anos</td><td>Dores frequentes sem causa médica. Queda no rendimento. Agressividade ou retraimento. Vergonha do próprio corpo. Recusa de trocar de roupa para a educação física.</td><td>Redações, conversas no recreio, pedidos para não voltar para casa.</td></tr><tr><td>12 a 14 anos</td><td>Isolamento, faltas, fugas de casa. Uso de álcool ou outras substâncias. Marcas escondidas por roupas longas. Namoro com pessoa bem mais velha. Presentes e dinheiro sem explicação.</td><td>Mudança de grupo, uso do celular, sono em sala, abandono de atividades de que gostava.</td></tr></tbody></table></div><h3>Sinais que pedem ação no mesmo dia</h3><ul><li>O aluno diz que tem medo de voltar para casa.</li><li>O aluno conta, mesmo que por alto, que alguém o machuca ou toca nele.</li><li>Há lesão que precisa de cuidado médico.</li><li>O aluno fala em morrer ou em se machucar.</li><li>Um adulto desconhecido tenta retirar o aluno da escola.</li></ul><div class=\"nota alerta\"><b>Sinal não é prova</b><br/>Vários desses sinais também aparecem por luto, separação dos pais, doença ou mudança de casa. O professor não precisa descobrir a causa. Precisa registrar o que viu e levar à direção.</div>"},{"id":"c13","titulo":"Violência sexual: o que o professor precisa saber","html":"<p>Violência sexual é qualquer ato de natureza sexual envolvendo criança ou adolescente. Ela inclui o abuso, com ou sem contato físico, e a exploração, quando há troca por dinheiro, presente ou favor. A criança nunca é responsável pelo que aconteceu.</p><p>Na maioria dos casos não há força física. O adulto ganha a confiança da criança aos poucos. Esse processo é chamado de aliciamento.</p><figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Aproximação</b><small>atenção, presentes, elogios</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Confiança</b><small>torna-se alguém especial</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Isolamento</b><small>momentos a sós, afastamento de outros adultos</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Segredo</b><small>\"isso fica só entre nós\"</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Controle</b><small>culpa, ameaça ou chantagem</small></div></div><figcaption>Figura. Como costuma ocorrer o aliciamento.</figcaption></figure><h3>Por que a criança não conta</h3><ul><li>Tem medo de não acreditarem nela.</li><li>Foi ameaçada ou acha que a família vai sofrer.</li><li>Sente culpa ou vergonha.</li><li>Gosta da pessoa e não quer que ela seja punida.</li><li>Não entende que o que acontece é errado.</li><li>Já tentou contar e não foi ouvida.</li></ul><h3>Como a criança conta</h3><p>Poucas crianças contam tudo de uma vez. É comum contar um pedaço para ver a reação do adulto, falar de \"um amigo\", mostrar em desenho ou em brincadeira, ou perguntar algo que parece fora de hora. A reação do adulto nesse primeiro momento decide se ela vai continuar.</p><div class=\"tb\"><table class=\"larga\"><thead><tr><th>A escola faz</th><th>A escola não faz</th></tr></thead><tbody><tr><td>Acolhe o relato espontâneo e acredita.</td><td>Não faz perguntas para obter detalhes.</td></tr><tr><td>Comunica à direção e ao Conselho Tutelar no mesmo dia.</td><td>Não chama o suspeito para conversar.</td></tr><tr><td>Mantém sigilo e rotina.</td><td>Não examina o corpo do aluno.</td></tr><tr><td>Registra o que foi dito, com as palavras do aluno.</td><td>Não pede que o aluno repita o relato a outros servidores.</td></tr><tr><td>Segue acompanhando o aluno.</td><td>Não promete segredo.</td></tr></tbody></table></div>"},{"id":"c14","titulo":"Riscos na internet","html":"<p>Boa parte da vida dos alunos passa pelo celular. Os mesmos riscos do mundo presencial aparecem ali, com alcance maior e longe dos olhos dos adultos.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Risco</th><th>Como aparece</th><th>O que orientar</th></tr></thead><tbody><tr><td>Aliciamento on-line</td><td>Um desconhecido, muitas vezes com perfil falso, conversa em jogos e redes, elogia, oferece presentes e pede segredo.</td><td>Não conversar em particular com quem não conhece pessoalmente. Contar a um adulto se alguém pedir segredo.</td></tr><tr><td>Pedido de imagens íntimas</td><td>Alguém pede fotos ou vídeos e depois ameaça divulgar para obter mais.</td><td>Nunca enviar. Se já enviou, não ceder à ameaça, guardar as provas e contar a um adulto. A culpa é de quem ameaça.</td></tr><tr><td>Exposição de colegas</td><td>Compartilhamento de fotos, montagens e vídeos para humilhar.</td><td>Não repassar. Quem compartilha também participa da agressão.</td></tr><tr><td>Cyberbullying</td><td>Ofensas, exclusão de grupos, perfis falsos e apelidos em redes e aplicativos.</td><td>Não responder, guardar as provas, bloquear e avisar a escola e a família.</td></tr><tr><td>Desafios perigosos</td><td>Vídeos que estimulam atos de risco para ganhar visualizações.</td><td>Conversar sobre a pressão do grupo e o direito de dizer não.</td></tr><tr><td>Conteúdo impróprio</td><td>Acesso a violência e pornografia.</td><td>Orientar as famílias sobre controles de uso e sobre acompanhar o que a criança vê.</td></tr></tbody></table></div><h3>Sinais de que algo vai mal na vida on-line</h3><ul><li>Esconde a tela quando um adulto se aproxima.</li><li>Fica muito abalado depois de usar o celular.</li><li>Apaga contas de repente ou cria perfis novos.</li><li>Recebe presentes, créditos ou dinheiro de quem a família não conhece.</li><li>Não quer mais ir à escola depois de algo que circulou nos grupos.</li></ul><div class=\"nota\"><b>Celular na escola</b><br/>A Lei nº 15.100/2025 restringe o uso de aparelhos eletrônicos pessoais pelos alunos durante as aulas, o recreio e os intervalos, com exceções para uso pedagógico, acessibilidade e saúde. A regra ajuda, mas não substitui a conversa sobre o uso fora da escola.</div><div class=\"nota\"><b>Onde buscar ajuda</b><br/>Crimes contra crianças na internet podem ser comunicados ao Disque 100 e à polícia. A escola orienta a família a guardar as conversas e as imagens como prova, sem repassá-las.</div>"},{"id":"c15","titulo":"Negligência, pobreza e trabalho infantil","html":"<p>Negligência é a omissão de quem tem condições de cuidar. Pobreza é a falta dessas condições. A diferença importa, porque a resposta da rede é diferente: a família pobre precisa de apoio, e não de punição.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Situação</th><th>Pode ser pobreza</th><th>Pode ser negligência</th><th>O que a escola faz</th></tr></thead><tbody><tr><td>Aluno chega com fome</td><td>A família não tem alimento.</td><td>Há alimento, mas ninguém cuida das refeições.</td><td>Garante a alimentação escolar e informa a direção.</td></tr><tr><td>Roupas e higiene precárias</td><td>Falta água, roupa ou produto de higiene.</td><td>Ninguém acompanha o banho e a troca de roupa.</td><td>Acolhe sem expor e aciona a direção.</td></tr><tr><td>Faltas frequentes</td><td>Falta transporte, o aluno cuida de irmãos.</td><td>Ninguém acorda nem leva o aluno.</td><td>Faz a busca ativa e registra.</td></tr><tr><td>Problema de saúde sem cuidado</td><td>Dificuldade de acesso ao serviço.</td><td>Recusa de levar ao atendimento.</td><td>Orienta a família e aciona a unidade de saúde.</td></tr></tbody></table></div><p>Nos dois casos a escola comunica à direção. Quando há pobreza, o caminho passa pelo CRAS e pelos programas sociais. Quando há negligência, pelo Conselho Tutelar. O ECA (art. 23) estabelece que a falta de recursos, sozinha, não é motivo para afastar a criança da família.</p><h3>Trabalho infantil</h3><p>A Constituição proíbe o trabalho antes dos 16 anos, salvo como aprendiz a partir dos 14. Antes dos 18, são proibidos o trabalho noturno, perigoso ou insalubre.</p><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Sinal na escola</th><th>O que pode indicar</th></tr></thead><tbody><tr><td>Cansaço e sono constantes</td><td>Trabalho à noite ou de madrugada.</td></tr><tr><td>Faltas em dias fixos</td><td>Feira, colheita, venda nas ruas.</td></tr><tr><td>Machucados nas mãos, queimaduras, dores nas costas</td><td>Trabalho pesado ou com ferramentas.</td></tr><tr><td>Dinheiro próprio e pressa de sair</td><td>Trabalho depois da aula.</td></tr><tr><td>Cuidado diário de irmãos e da casa</td><td>Trabalho doméstico que impede o estudo.</td></tr></tbody></table></div><div class=\"nota\"><b>Ajudar em casa não é trabalho infantil</b><br/>Arrumar a própria cama e ajudar em tarefas leves faz parte da educação. O problema começa quando a atividade prejudica a saúde, o descanso, a brincadeira ou a escola.</div>"},{"id":"c16","titulo":"Sofrimento emocional e autolesão","html":"<p>Alguns alunos mostram o sofrimento machucando o próprio corpo ou falando em morrer. Esses sinais precisam ser levados a sério sempre. Eles não são \"para chamar atenção\", e mesmo quando são um pedido de atenção, é de atenção que o aluno precisa.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Sinais de alerta</th><th>O que fazer</th><th>O que evitar</th></tr></thead><tbody><tr><td>Roupas longas no calor, recusa de mostrar braços e pernas. Marcas repetidas.</td><td>Conversar em particular, com calma: \"Tenho notado que você não está bem. Quero ajudar.\"</td><td>Pedir para ver as marcas ou reagir com espanto.</td></tr><tr><td>Frases como \"queria sumir\" ou \"ninguém sentiria falta\".</td><td>Ouvir sem interromper e dizer que vai buscar ajuda.</td><td>Dizer que é bobagem ou que tem gente em situação pior.</td></tr><tr><td>Despedidas, doação de objetos de que gostava.</td><td>Não deixar o aluno sozinho e avisar a direção imediatamente.</td><td>Esperar o dia seguinte.</td></tr><tr><td>Isolamento, tristeza que não passa, perda de interesse.</td><td>Registrar e levar à coordenação.</td><td>Prometer segredo.</td></tr></tbody></table></div><ol class=\"passos\"><li>Acolha e mantenha o aluno acompanhado.</li><li>Avise a direção no mesmo momento.</li><li>A direção chama os responsáveis, salvo quando há suspeita de que a violência venha de casa.</li><li>A escola comunica ao Conselho Tutelar, em sigilo, como determina a Lei nº 13.819/2019.</li><li>A família é orientada a procurar a unidade de saúde ou o CAPS.</li><li>A escola combina com a família como receber o aluno de volta.</li></ol><div class=\"nota\"><b>Falar não incentiva</b><br/>Perguntar com cuidado como o aluno está não coloca a ideia na cabeça dele. Dá a ele a chance de pedir ajuda.</div><div class=\"nota alerta\"><b>Em situação de risco imediato</b><br/>Ligue para o SAMU, no 192. O Centro de Valorização da Vida atende pelo telefone 188, todos os dias, a qualquer hora.</div><p>Na escola, o assunto é tratado com discrição. Não se comentam detalhes com a turma, não se divulgam imagens e não se fazem homenagens que tornem o ato atraente para outros alunos.</p>"},{"id":"c17","titulo":"Roteiros de conversa","html":"<p>Ter as palavras prontas ajuda nos momentos difíceis. Os roteiros abaixo são exemplos. Adapte à idade do aluno e ao seu jeito de falar.</p><div class=\"dialogo\"><div class=\"tt\">Roteiro de conversa · quando o aluno começa a contar</div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">Obrigado por confiar em mim. Estou aqui para ouvir.</div></div><div class=\"f o\"><div class=\"q\">Aluno</div><div class=\"b\">Mas você não pode contar para ninguém.</div></div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">Não posso prometer segredo, porque quero que você fique protegido. Vou contar só para quem pode ajudar.</div></div><div class=\"f o\"><div class=\"q\">Aluno</div><div class=\"b\">Vão brigar comigo?</div></div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">Não. Você não fez nada de errado. O que aconteceu não é culpa sua.</div></div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">Agora vou falar com a diretora. Depois eu te conto o que vai acontecer.</div></div></div><div class=\"dialogo\"><div class=\"tt\">Roteiro de conversa · quando você percebe que o aluno não está bem</div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">Tenho notado você mais calado nestes dias. Aconteceu alguma coisa?</div></div><div class=\"f o\"><div class=\"q\">Aluno</div><div class=\"b\">Nada.</div></div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">Tudo bem. Se quiser conversar, pode me procurar. Estou aqui.</div></div></div><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Frases que ajudam</th><th>Frases que atrapalham</th></tr></thead><tbody><tr><td>\"Eu acredito em você.\"</td><td>\"Tem certeza? Isso é muito grave.\"</td></tr><tr><td>\"Não é culpa sua.\"</td><td>\"Por que você não contou antes?\"</td></tr><tr><td>\"Você fez certo em me contar.\"</td><td>\"Por que você deixou?\"</td></tr><tr><td>\"Vou buscar ajuda para você.\"</td><td>\"Vou falar com seu pai agora.\"</td></tr><tr><td>\"Pode falar do seu jeito.\"</td><td>\"Me conta tudo, desde o começo, com detalhes.\"</td></tr><tr><td>\"Estou aqui.\"</td><td>\"Não acredito que ele fez isso!\"</td></tr></tbody></table></div><h3>Cuidados durante a conversa</h3><ul><li>Escolha um lugar reservado, mas visível, com a porta aberta ou outro adulto por perto.</li><li>Fique na altura do aluno e deixe que ele fale no tempo dele.</li><li>Não complete as frases nem sugira palavras.</li><li>Não demonstre choque, nojo ou raiva.</li><li>Não fale mal de quem o aluno citou.</li><li>Encerre dizendo o que vai acontecer agora.</li></ul><div class=\"pratica\"><div class=\"tt\">Para praticar · ensaie antes de precisar</div><div class=\"q\"><b>1.</b> Escreva, com as suas palavras, como você responderia a um aluno que pede segredo.<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>2.</b> Que lugar da sua escola serve para uma conversa reservada e segura?<div class=\"ln\"></div><div class=\"ln\"></div></div></div>"},{"id":"c18","titulo":"Como escrever o registro","html":"<p>O registro escrito é o que permite à rede de proteção agir sem obrigar o aluno a repetir o relato. Ele deve conter fatos, e não opiniões.</p><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Escreva assim (fato)</th><th>Evite escrever assim (interpretação)</th></tr></thead><tbody><tr><td>\"No dia 10, o aluno chegou com um hematoma no braço esquerdo.\"</td><td>\"O aluno apanha em casa.\"</td></tr><tr><td>\"Disse: 'meu tio não deixa eu contar'.\"</td><td>\"O tio abusa do aluno.\"</td></tr><tr><td>\"Dormiu na aula em quatro dias desta semana.\"</td><td>\"A família é desestruturada.\"</td></tr><tr><td>\"Chorou ao ser chamada pela mãe na saída.\"</td><td>\"A mãe é violenta.\"</td></tr></tbody></table></div><h3>Modelo de registro</h3><div class=\"rapido\"><p><b>Escola:</b> ______________________________ <b>Data do registro:</b> ____/____/______</p><p><b>Aluno (iniciais), ano e turma:</b> ______________________________</p><p><b>Quem registra e função:</b> ______________________________</p><p><b>O que foi observado ou ouvido (data, hora, local e palavras do aluno, entre aspas):</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm;margin-bottom:3mm\"></div><p><b>Quem estava presente:</b> ______________________________</p><p><b>A quem foi comunicado na escola, data e hora:</b> ______________________________</p><p><b>Encaminhamento feito pela direção:</b> ______________________________</p><p><b>Assinatura:</b> ______________________________</p></div><h3>Cuidados com o registro</h3><ul><li>Escreva no mesmo dia, enquanto lembra das palavras exatas.</li><li>Entregue à direção. Não guarde cópia no celular nem em caderno pessoal.</li><li>Não envie por aplicativo de mensagens.</li><li>Não anote o caso em diário de classe, ata de conselho ou outro documento que circule.</li><li>A direção guarda o registro em local com acesso restrito.</li></ul><div class=\"nota\"><b>Fotografar marcas</b><br/>O servidor não fotografa o corpo do aluno. O registro de lesões cabe ao serviço de saúde e à perícia.</div>"},{"id":"c19","titulo":"Depois da comunicação","html":"<p>Muitos servidores deixam de comunicar por não saber o que acontece depois. O caminho abaixo mostra as etapas mais comuns. Cada caso segue o que a rede avaliar necessário.</p><figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Conselho Tutelar</b><small>recebe e avalia o risco</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Medidas de proteção</b><small>orienta, encaminha, requisita serviços</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Saúde e assistência</b><small>atendem o aluno e a família</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Polícia e Justiça</b><small>apuram quando há crime</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Escola</b><small>acolhe e acompanha</small></div></div><figcaption>Figura. O que acontece depois que a escola comunica.</figcaption></figure><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Termo</th><th>O que é</th><th>Quem faz</th></tr></thead><tbody><tr><td>Revelação espontânea</td><td>O aluno conta por iniciativa própria.</td><td>Qualquer adulto de confiança, inclusive o professor, que apenas acolhe.</td></tr><tr><td>Escuta especializada</td><td>Entrevista limitada ao necessário para proteger.</td><td>Profissional preparado da rede de proteção.</td></tr><tr><td>Depoimento especial</td><td>Oitiva perante a polícia ou a Justiça, em ambiente adequado.</td><td>Profissional especializado, com gravação, para evitar repetições.</td></tr><tr><td>Medida de proteção</td><td>Decisão que garante direitos: atendimento, acompanhamento, afastamento do agressor.</td><td>Conselho Tutelar e Justiça.</td></tr></tbody></table></div><h3>O papel da escola nessa fase</h3><ul><li>Manter a rotina do aluno, que é fonte de segurança.</li><li>Tratar o aluno como antes, sem piedade nem curiosidade.</li><li>Observar e registrar mudanças.</li><li>Responder aos pedidos de informação do Conselho Tutelar e da Justiça, pela direção.</li><li>Cuidar das faltas: avisar a rede se o aluno deixar de vir.</li><li>Não comentar o caso com quem não precisa saber.</li></ul><div class=\"nota\"><b>E se nada parecer acontecer?</b><br/>A rede nem sempre pode informar à escola o que foi feito, por sigilo. Se os sinais continuarem, a direção comunica de novo e, se preciso, aciona a Secretaria e o Ministério Público.</div><h3>Quando avisar os responsáveis</h3><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Situação</th><th>Conduta</th></tr></thead><tbody><tr><td>A suspeita envolve alguém de fora da família</td><td>A direção chama os responsáveis e orienta sobre a rede de proteção.</td></tr><tr><td>A suspeita envolve alguém da casa</td><td>A direção comunica primeiro ao Conselho Tutelar, que decide como e quando falar com a família.</td></tr><tr><td>O responsável procura a escola irritado com a comunicação</td><td>A direção recebe, explica o dever legal e não revela quem percebeu.</td></tr></tbody></table></div>"},{"id":"c20","titulo":"Bullying: quem participa e por quê","html":"<p>O bullying não acontece só entre duas pessoas. Ele depende de um grupo que assiste. Entender os papéis mostra onde a escola pode agir.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Papel</th><th>O que faz</th><th>Do que precisa</th></tr></thead><tbody><tr><td>Alvo</td><td>Sofre as agressões repetidas e não consegue se defender.</td><td>Proteção imediata, escuta e recuperação da confiança.</td></tr><tr><td>Autor</td><td>Agride, em geral para ganhar posição no grupo.</td><td>Limite claro, responsabilização e ajuda para mudar.</td></tr><tr><td>Apoiadores</td><td>Riem, filmam, repassam.</td><td>Entender que também participam.</td></tr><tr><td>Espectadores</td><td>Veem e se calam, por medo de serem os próximos.</td><td>Saber como ajudar sem se expor.</td></tr><tr><td>Defensores</td><td>Ficam ao lado do alvo ou avisam um adulto.</td><td>Reconhecimento e apoio.</td></tr></tbody></table></div><p>A maior parte da turma está entre os espectadores. Quando eles deixam de rir e passam a apoiar o colega, a agressão perde a plateia e tende a parar. Por isso o trabalho com a turma inteira é o que mais funciona.</p><h3>Quem costuma virar alvo</h3><ul><li>Alunos novos na escola ou na turma.</li><li>Alunos com deficiência, com transtornos ou com dificuldade de aprender.</li><li>Alunos que se destacam: os que tiram notas altas e os que tiram notas baixas.</li><li>Alunos com aparência, sotaque, religião, cor ou jeito de ser diferente do grupo.</li><li>Alunos mais tímidos, com poucos amigos.</li></ul><h3>Cyberbullying</h3><p>É o bullying feito por meios digitais. Ele segue o aluno até em casa, alcança muita gente em pouco tempo e deixa registro. A Lei nº 14.811/2024 prevê pena mais grave quando a intimidação ocorre pela internet.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Diferença</th><th>Presencial</th><th>Digital</th></tr></thead><tbody><tr><td>Quando ocorre</td><td>No horário da escola.</td><td>A qualquer hora.</td></tr><tr><td>Quem vê</td><td>Quem está perto.</td><td>Centenas de pessoas.</td></tr><tr><td>Quem agride</td><td>É conhecido.</td><td>Pode se esconder em perfil falso.</td></tr><tr><td>O que resta</td><td>A lembrança.</td><td>Imagens e mensagens que voltam a circular.</td></tr></tbody></table></div><div class=\"nota\"><b>O que aconteceu fora da escola também é da escola</b><br/>Quando o que circula nos grupos afeta a convivência e a frequência do aluno, a escola age: acolhe, conversa com os envolvidos e chama as famílias.</div>"},{"id":"c21","titulo":"Conversas que restauram","html":"<p>Punir o autor pode ser necessário, mas sozinho não resolve. A agressão costuma voltar, mais escondida. As práticas restaurativas buscam três coisas: que o autor entenda o dano, que o dano seja reparado e que a convivência seja refeita.</p><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Pergunta restaurativa</th><th>Para que serve</th></tr></thead><tbody><tr><td>\"O que aconteceu?\"</td><td>Ouvir a versão de cada um, sem julgamento.</td></tr><tr><td>\"O que você pensou na hora?\"</td><td>Levar a pessoa a olhar para a própria escolha.</td></tr><tr><td>\"Quem foi afetado e como?\"</td><td>Fazer enxergar o dano.</td></tr><tr><td>\"O que é preciso para consertar?\"</td><td>Construir a reparação.</td></tr><tr><td>\"O que você faz diferente daqui em diante?\"</td><td>Firmar um compromisso.</td></tr></tbody></table></div><div class=\"dialogo\"><div class=\"tt\">Roteiro de conversa · com o aluno que agrediu</div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">Quero entender o que aconteceu no recreio. Me conta do seu jeito.</div></div><div class=\"f o\"><div class=\"q\">Aluno</div><div class=\"b\">Era brincadeira. Todo mundo riu.</div></div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">Todo mundo riu. E o Pedro, como você acha que ele ficou?</div></div><div class=\"f o\"><div class=\"q\">Aluno</div><div class=\"b\">Sei lá. Ficou quieto.</div></div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">Ele faltou três dias nesta semana. O que você pode fazer para isso parar?</div></div></div><div class=\"nota alerta\"><b>Não coloque alvo e autor frente a frente</b><br/>No bullying há desequilíbrio de poder. Uma conversa conjunta pode intimidar ainda mais a vítima. Converse em separado. O encontro só acontece se o alvo quiser e se sentir seguro.</div><h3>Roda de conversa com a turma</h3><ol class=\"passos\"><li>Forme um círculo, com todos no mesmo nível.</li><li>Combine as regras: fala um por vez, ninguém é obrigado a falar, o que é dito fica na roda.</li><li>Proponha uma pergunta geral, sem citar nomes: \"O que faz uma pessoa se sentir parte da turma?\"</li><li>Passe um objeto que indica quem está com a palavra.</li><li>Feche com um combinado da turma, escrito e exposto na sala.</li><li>Retome o combinado depois de duas semanas.</li></ol><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Medida com o autor</th><th>Exemplo</th></tr></thead><tbody><tr><td>Reparação</td><td>Desfazer o que fez: apagar a postagem, devolver o objeto, pedir desculpas se o alvo aceitar.</td></tr><tr><td>Responsabilidade</td><td>Assumir uma tarefa de cuidado com a turma.</td></tr><tr><td>Acompanhamento</td><td>Encontros semanais com a coordenação por um período.</td></tr><tr><td>Família</td><td>Conversa com os responsáveis sobre o que ocorreu e o que se espera.</td></tr><tr><td>Medida disciplinar</td><td>Conforme o regimento escolar, sem humilhação e sem afastar da aprendizagem.</td></tr></tbody></table></div>"},{"id":"c22","titulo":"Ensinar a criança a se proteger","html":"<p>A prevenção mais eficaz é a criança saber que o corpo é dela, que pode dizer não e que tem a quem contar. Esse trabalho é feito com naturalidade, em linguagem adequada à idade, e combinado com a coordenação e as famílias.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Idade</th><th>O que trabalhar</th><th>Como</th></tr></thead><tbody><tr><td>6 a 8 anos</td><td>Nomes das partes do corpo. Toques que são de cuidado e toques que incomodam. Segredos bons e segredos que fazem mal. Adultos de confiança.</td><td>Histórias, desenhos e a \"mão da confiança\": cinco adultos a quem a criança pode contar.</td></tr><tr><td>9 a 11 anos</td><td>Mudanças do corpo. Privacidade. Pressão de colegas e de adultos. Uso seguro da internet.</td><td>Rodas de conversa, situações para discutir: \"o que você faria se...\".</td></tr><tr><td>12 a 14 anos</td><td>Consentimento e respeito. Relações abusivas. Exposição de imagens. Onde pedir ajuda.</td><td>Debates, estudo de casos fictícios, produção de campanhas pelos alunos.</td></tr></tbody></table></div><h3>Três mensagens para repetir sempre</h3><ul><li>\"O seu corpo é seu.\"</li><li>\"Você pode dizer não, mesmo para um adulto.\"</li><li>\"Se alguém pedir segredo sobre algo que incomoda, conte a um adulto de confiança. Se ele não ouvir, conte a outro.\"</li></ul><div class=\"nota\"><b>Trabalho combinado</b><br/>Avise as famílias antes de tratar do tema e explique o objetivo. Famílias informadas costumam apoiar. Use os materiais indicados pela coordenação e pela Secretaria.</div><h3>O que a escola inteira pode fazer</h3><ul class=\"chk\"><li><span></span>Todo aluno sabe o nome de pelo menos um adulto da escola a quem pode recorrer.</li><li><span></span>Há um canal simples para o aluno pedir ajuda, como uma caixa de recados ou um horário de escuta.</li><li><span></span>Os espaços com menos supervisão têm adulto presente nos intervalos.</li><li><span></span>Nenhum adulto fica sozinho com um aluno em sala fechada.</li><li><span></span>Visitantes e prestadores de serviço são identificados e acompanhados.</li><li><span></span>A saída dos alunos é feita apenas com os responsáveis autorizados.</li><li><span></span>O tema é retomado todo ano, e não apenas em uma data.</li></ul>"},{"id":"c23","titulo":"O plano de proteção da escola","html":"<p>A proteção funciona quando não depende de uma só pessoa. O plano de proteção é um documento curto, feito pela direção com a equipe, que diz quem faz o quê.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Parte do plano</th><th>O que define</th></tr></thead><tbody><tr><td>Referências da escola</td><td>Dois servidores, além da direção, que recebem as comunicações dos colegas.</td></tr><tr><td>Fluxo interno</td><td>A quem o servidor comunica, em quanto tempo e como registrar.</td></tr><tr><td>Contatos da rede</td><td>Telefones e nomes do Conselho Tutelar, do CRAS, do CREAS, da unidade de saúde e da Secretaria.</td></tr><tr><td>Guarda dos registros</td><td>Onde ficam e quem tem acesso.</td></tr><tr><td>Prevenção</td><td>Ações com os alunos, as famílias e a equipe ao longo do ano.</td></tr><tr><td>Formação</td><td>Quando a equipe estuda o tema e como os novos servidores são orientados.</td></tr><tr><td>Revisão</td><td>Data para avaliar o plano, ao menos uma vez por ano.</td></tr></tbody></table></div><h3>Calendário de prevenção</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Período</th><th>Ação</th></tr></thead><tbody><tr><td>Início do ano</td><td>Apresentar o plano à equipe. Combinados de convivência em cada turma. Reunião com os responsáveis.</td></tr><tr><td>Abril</td><td>Dia Nacional de Combate ao Bullying e à Violência na Escola, em 7 de abril.</td></tr><tr><td>Maio</td><td>Dia Nacional de Combate ao Abuso e à Exploração Sexual de Crianças e Adolescentes, em 18 de maio.</td></tr><tr><td>Junho</td><td>Dia Mundial contra o Trabalho Infantil, em 12 de junho.</td></tr><tr><td>Setembro</td><td>Mês de valorização da vida e de atenção à saúde mental.</td></tr><tr><td>Todo bimestre</td><td>Roda de conversa em cada turma e revisão dos casos em acompanhamento.</td></tr><tr><td>Fim do ano</td><td>Avaliação do plano e ajustes para o ano seguinte.</td></tr></tbody></table></div><div class=\"nota\"><b>Datas ajudam, rotina protege</b><br/>As datas dão visibilidade ao tema. O que protege o aluno é a atenção de todos os dias.</div>"},{"id":"c24","titulo":"Casos para estudo","html":"<div class=\"caso\"><div class=\"tt\">Exemplo de uso · a redação que dizia mais do que o tema</div><p><b>Situação.</b> Em uma redação sobre a família, uma aluna do 7º ano escreve que tem medo de ficar em casa à noite quando a mãe sai para trabalhar.</p><p><b>O que fazer.</b></p><ol><li>Não comente o texto diante da turma.</li><li>Converse em particular: \"Li o seu texto e fiquei pensando em você. Quer me contar mais?\"</li><li>Ouça sem perguntar detalhes.</li><li>Registre as palavras da aluna e entregue à direção no mesmo dia.</li><li>A direção comunica ao Conselho Tutelar.</li></ol><p><b>Resultado esperado.</b> A aluna é ouvida por profissional da rede, e a escola segue acompanhando.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · o menino que sempre tinha fome</div><p><b>Situação.</b> Um aluno do 3º ano pede para repetir a merenda todos os dias e guarda comida na mochila. Chega com as mesmas roupas durante a semana.</p><p><b>O que fazer.</b></p><ol><li>Garanta a alimentação sem expor o aluno.</li><li>Registre o que observa, com datas.</li><li>Leve à direção.</li><li>A direção conversa com a família e aciona o CRAS.</li><li>Se houver sinais de omissão de cuidados, a direção comunica ao Conselho Tutelar.</li></ol><p><b>Resultado esperado.</b> A família passa a ser acompanhada pela assistência social.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · a foto que circulou no grupo</div><p><b>Situação.</b> Uma montagem com o rosto de uma aluna do 8º ano circula nos grupos da turma. Ela para de ir à escola.</p><p><b>O que fazer.</b></p><ol><li>A direção acolhe a aluna e a família e orienta a guardar as provas.</li><li>Os alunos que criaram e repassaram são ouvidos em separado, com as famílias.</li><li>A escola pede que o conteúdo seja apagado e informa que o ato pode ser crime.</li><li>A turma participa de roda de conversa sobre exposição, sem citar o caso.</li><li>A família é orientada sobre o registro na polícia.</li></ol><p><b>Resultado esperado.</b> A aluna volta às aulas com acompanhamento da coordenação.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · as marcas no braço</div><p><b>Situação.</b> Uma professora nota cortes no antebraço de um aluno do 9º ano, que usa moletom mesmo no calor.</p><p><b>O que fazer.</b></p><ol><li>Converse em particular, sem pedir para ver as marcas.</li><li>Diga que está preocupada e que vai buscar ajuda.</li><li>Avise a direção no mesmo momento.</li><li>A direção chama os responsáveis, orienta a busca do serviço de saúde e comunica ao Conselho Tutelar, em sigilo.</li><li>A escola combina com o aluno um adulto de referência a quem ele pode recorrer.</li></ol><p><b>Resultado esperado.</b> O aluno inicia acompanhamento na rede de saúde, e a escola mantém a rotina.</p></div><div class=\"pratica\"><div class=\"tt\">Para praticar · agora é com você</div><div class=\"q\"><b>1.</b> Lembre de uma situação real da sua escola, sem citar nomes. O que foi feito?<div class=\"ln\"></div><div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>2.</b> O que você faria de diferente depois de ler este guia?<div class=\"ln\"></div><div class=\"ln\"></div><div class=\"ln\"></div></div></div>"},{"id":"c25","titulo":"Erros comuns e como evitá-los","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Erro</th><th>Por que é um problema</th><th>O que fazer</th></tr></thead><tbody><tr><td>Esperar ter certeza</td><td>A violência continua enquanto a escola espera.</td><td>Comunicar diante da suspeita.</td></tr><tr><td>Investigar por conta própria</td><td>Pode alertar o agressor e prejudicar a apuração.</td><td>Acolher, registrar e comunicar.</td></tr><tr><td>Chamar a família antes de avaliar o risco</td><td>Se o agressor está em casa, a criança pode ser punida ou silenciada.</td><td>A direção decide com o Conselho Tutelar.</td></tr><tr><td>Pedir que o aluno repita o relato</td><td>Cada repetição causa novo sofrimento e pode alterar o relato.</td><td>Uma pessoa ouve e registra.</td></tr><tr><td>Comentar o caso na sala dos professores</td><td>Expõe o aluno e pode chegar à família.</td><td>Falar apenas com a direção.</td></tr><tr><td>Tratar o aluno de forma diferente</td><td>Ele percebe e se sente marcado.</td><td>Manter a rotina e o carinho de sempre.</td></tr><tr><td>Resolver o bullying com um pedido de desculpas forçado</td><td>A agressão continua escondida.</td><td>Acompanhar por semanas.</td></tr><tr><td>Culpar o alvo</td><td>\"Ele também provoca\" transfere a responsabilidade.</td><td>Proteger primeiro, entender depois.</td></tr><tr><td>Agir sozinho</td><td>O servidor se expõe e o caso fica sem registro.</td><td>Seguir o fluxo da escola.</td></tr><tr><td>Achar que comunicar encerra o caso</td><td>O aluno continua precisando da escola.</td><td>Acompanhar e comunicar de novo, se preciso.</td></tr></tbody></table></div><h3>Cuidar de quem cuida</h3><p>Ouvir o relato de uma criança que sofre violência pesa. É comum o servidor sentir tristeza, raiva, impotência ou culpa por não ter percebido antes. Esses sentimentos não são fraqueza.</p><ul><li>Converse com a direção ou a coordenação sobre como você ficou, sem expor detalhes do caso.</li><li>Não leve o caso sozinho para casa: divida a responsabilidade com a equipe.</li><li>Respeite os seus limites e peça apoio se o caso tocar em algo da sua própria história.</li><li>Procure o serviço de saúde do servidor quando o sofrimento persistir.</li><li>Lembre que você fez a sua parte ao perceber e comunicar.</li></ul><div class=\"nota\"><b>O que está ao seu alcance</b><br/>O professor não consegue resolver a vida do aluno fora da escola. Consegue ser um adulto que percebe, acredita e age. Para muitas crianças, isso muda tudo.</div>"},{"id":"c26","titulo":"Racismo e discriminação como violência","html":"<p>Ofensas, apelidos, exclusão e tratamento desigual por causa da cor, da origem, da religião, da deficiência, do corpo ou do jeito de ser ferem o aluno e prejudicam a aprendizagem. Quando se repetem entre colegas, são bullying. Quando têm motivação racial, são também crime.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Forma</th><th>Como aparece na escola</th><th>O que diz a lei</th></tr></thead><tbody><tr><td>Racismo e injúria racial</td><td>Apelidos e piadas sobre cor e cabelo. Recusa de sentar junto ou de formar grupo. Comparações ofensivas.</td><td>São crimes previstos na Lei nº 7.716/1989. A Lei nº 14.532/2023 equiparou a injúria racial ao racismo.</td></tr><tr><td>Intolerância religiosa</td><td>Zombaria de roupas, símbolos e práticas. Tratar uma religião como coisa do mal.</td><td>A liberdade de crença é garantida pela Constituição. A discriminação é crime.</td></tr><tr><td>Discriminação por deficiência</td><td>Imitação, exclusão de brincadeiras, falar do colega como incapaz.</td><td>A Lei nº 13.146/2015 pune a discriminação da pessoa com deficiência.</td></tr><tr><td>Discriminação por gênero e orientação sexual</td><td>Xingamentos, ameaças, exclusão.</td><td>Condutas equiparadas ao crime de racismo, conforme decisão do Supremo Tribunal Federal.</td></tr><tr><td>Discriminação por condição social e origem</td><td>Zombaria de roupa, material, moradia, sotaque.</td><td>Fere o direito ao respeito e à dignidade, previsto no Estatuto da Criança e do Adolescente.</td></tr></tbody></table></div><h3>O que o adulto faz</h3><ol class=\"passos\"><li>Interrompe na hora: \"Isso não é brincadeira. Aqui não se fala assim.\"</li><li>Acolhe quem foi atingido, em particular, e diz que ele não fez nada de errado.</li><li>Conversa com quem ofendeu, explicando o dano e a gravidade.</li><li>Comunica à direção, que chama as famílias e registra.</li><li>Trabalha o tema com a turma, sem expor os envolvidos.</li><li>Acompanha nas semanas seguintes.</li></ol><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Evite dizer</th><th>Por quê</th></tr></thead><tbody><tr><td>\"Foi só uma brincadeira.\"</td><td>Diminui a dor de quem foi atingido.</td></tr><tr><td>\"Não ligue.\"</td><td>Coloca a responsabilidade em quem sofre.</td></tr><tr><td>\"Somos todos iguais.\"</td><td>Encerra a conversa sem tratar do que aconteceu.</td></tr><tr><td>\"Ele também provoca.\"</td><td>Justifica a agressão.</td></tr></tbody></table></div><h3>Prevenção no currículo</h3><ul><li>O ensino da história e da cultura afro-brasileira e indígena é obrigatório em toda a educação básica.</li><li>Livros, imagens e exemplos usados em aula devem mostrar pessoas de origens diversas em papéis valorizados.</li><li>A escola observa quem é elogiado, quem é chamado ao quadro e quem é punido com mais frequência.</li><li>As famílias são ouvidas sobre como os filhos se sentem na escola.</li></ul>"},{"id":"c27","titulo":"Perguntas frequentes","html":"<div class=\"tb\"><table class=\"larga\"><thead><tr><th>Pergunta</th><th>Resposta</th></tr></thead><tbody><tr><td>E se eu comunicar e não for verdade?</td><td>Quem comunica de boa-fé uma suspeita cumpre a lei. A apuração cabe aos órgãos competentes.</td></tr><tr><td>A família vai saber que fui eu?</td><td>A comunicação é feita pela escola, de forma institucional. A direção não revela quem percebeu.</td></tr><tr><td>Posso comunicar direto ao Conselho Tutelar?</td><td>O caminho é a direção. Se a direção se omitir, ou se a suspeita envolver alguém da escola, o servidor comunica diretamente ou pelo Disque 100.</td></tr><tr><td>O aluno pediu para eu não contar.</td><td>Explique que você precisa contar a quem pode protegê-lo. O dever de proteger vem antes do segredo.</td></tr><tr><td>Preciso de prova?</td><td>Não. Basta a suspeita fundada em sinais ou em um relato.</td></tr><tr><td>Devo perguntar detalhes para ter certeza?</td><td>Não. Perguntas podem causar sofrimento e prejudicar a apuração.</td></tr><tr><td>Posso conversar com o suspeito?</td><td>Não. Isso pode colocar a criança em risco.</td></tr><tr><td>E se o suspeito for um colega de trabalho?</td><td>Comunique à direção. Se envolver a direção, à Secretaria. Guarde sigilo.</td></tr><tr><td>O que faço se a criança voltar atrás?</td><td>Mantenha a comunicação. Voltar atrás é comum e não significa que nada aconteceu.</td></tr><tr><td>Briga de recreio é bullying?</td><td>Não. Bullying é repetido, intencional e com desequilíbrio de poder.</td></tr><tr><td>Posso obrigar os dois a se abraçarem e fazerem as pazes?</td><td>Não. Em caso de bullying, isso expõe a vítima.</td></tr><tr><td>E se os pais do autor negarem?</td><td>Apresente os fatos registrados, explique as medidas da escola e a previsão legal.</td></tr><tr><td>O que aconteceu fora da escola é problema nosso?</td><td>Quando afeta o aluno e a convivência, sim. A proteção não para no portão.</td></tr><tr><td>Tenho medo de represália.</td><td>Diga à direção. A comunicação é institucional, e a Secretaria apoia.</td></tr></tbody></table></div>"},{"id":"c28","titulo":"Roteiro de estudo em grupo","html":"<p>Este guia rende mais quando é estudado com colegas. O roteiro abaixo divide a leitura em encontros de uma hora, que podem acontecer nas reuniões pedagógicas ou em grupos de estudo. Cada pessoa lê os capítulos antes do encontro.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Encontro</th><th>Capítulos</th><th>Perguntas para a conversa</th></tr></thead><tbody><tr><td>1</td><td>Do início até \"O caminho da comunicação\"</td><td>Todos conhecem o nosso fluxo interno? Quem são as referências da escola?</td></tr><tr><td>2</td><td>De \"Bullying\" até \"Mitos que atrapalham\"</td><td>Que mitos ainda circulam aqui? Como identificamos o bullying?</td></tr><tr><td>3</td><td>De \"Sinais em cada idade\" até \"Sofrimento emocional\"</td><td>Que sinais já observamos e deixamos passar? O que orientamos sobre a internet?</td></tr><tr><td>4</td><td>De \"Roteiros de conversa\" até \"Depois da comunicação\"</td><td>Ensaio dos roteiros em duplas. Onde ficam os nossos registros?</td></tr><tr><td>5</td><td>De \"Bullying: quem participa\" até o final</td><td>Como trabalhamos com as turmas? Qual é o nosso plano de proteção?</td></tr></tbody></table></div><h3>Como conduzir cada encontro</h3><ol class=\"passos\"><li>Rodada inicial: cada um diz, em uma frase, o que mais chamou a atenção na leitura.</li><li>Discussão das perguntas, primeiro em duplas e depois no grupo.</li><li>Análise de um dos casos do guia ou de uma situação da escola, sem citar nomes.</li><li>Combinado: o que cada um vai experimentar até o próximo encontro.</li><li>No encontro seguinte, a conversa começa pelo relato do que foi experimentado.</li></ol><div class=\"nota\"><b>Registro</b><br/>Os casos discutidos no grupo não trazem nomes, e o que se conversa não sai da sala.</div>"},{"id":"c29","titulo":"Referências","html":"<ul><li>Estatuto da Criança e do Adolescente (Lei nº 8.069/1990), arts. 13, 56 e 245.</li><li>Lei nº 13.431/2017, sobre a escuta de crianças e adolescentes vítimas ou testemunhas de violência.</li><li>Lei nº 14.344/2022, sobre a violência doméstica e familiar contra criança e adolescente.</li><li>Lei nº 13.185/2015, Programa de Combate à Intimidação Sistemática.</li><li>Lei nº 14.811/2024, medidas de proteção contra a violência em estabelecimentos educacionais.</li><li>Ministério da Educação: programa Escola que Protege.</li></ul>"},{"id":"c30","titulo":"Verifique o que aprendeu","html":"<div class=\"quiz\"><div class=\"qz\"><p><b>1.</b> Diante da suspeita de violência contra um aluno, o professor deve:</p><ol type=\"a\"><li>Guardar segredo.</li><li>Ter certeza antes de falar.</li><li>Comunicar à direção no mesmo dia.</li><li>Conversar com a família apontada.</li></ol></div><div class=\"qz\"><p><b>2.</b> Quando um aluno relata uma violência, o adequado é:</p><ol type=\"a\"><li>Ouvir, acreditar e não fazer perguntas sobre detalhes.</li><li>Pedir que repita à turma.</li><li>Prometer segredo.</li><li>Pedir todos os detalhes.</li></ol></div><div class=\"qz\"><p><b>3.</b> O que caracteriza o bullying?</p><ol type=\"a\"><li>Uma crítica a um trabalho.</li><li>Uma brincadeira em que todos riem.</li><li>Uma briga isolada.</li><li>Agressão intencional e repetida, com desequilíbrio de poder.</li></ol></div><div class=\"qz\"><p><b>4.</b> No bullying, colocar vítima e autor frente a frente:</p><ol type=\"a\"><li>É o primeiro passo.</li><li>Não é recomendado: pode expor ainda mais a vítima.</li><li>É obrigatório por lei.</li><li>Resolve na maioria dos casos.</li></ol></div></div><div class=\"gab\"><b>Respostas</b><p><b>1.</b> c) Comunicar à direção no mesmo dia. A escola comunica a suspeita ao Conselho Tutelar.</p><p><b>2.</b> a) Ouvir, acreditar e não fazer perguntas sobre detalhes. A escuta detalhada cabe a profissional preparado.</p><p><b>3.</b> d) Agressão intencional e repetida, com desequilíbrio de poder. Repetição e desequilíbrio são as marcas.</p><p><b>4.</b> b) Não é recomendado: pode expor ainda mais a vítima. Cada um é ouvido em separado.</p></div>"},{"id":"c31","titulo":"Os contatos da rede de proteção da minha escola","html":"<p>Preencha esta página com a direção e mantenha uma cópia em local de fácil acesso para a equipe. Em uma situação urgente, ninguém deve precisar procurar um telefone.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Serviço</th><th>Nome da pessoa de referência</th><th>Telefone</th><th>Endereço e horário</th></tr></thead><tbody><tr><td>Conselho Tutelar</td><td> </td><td></td><td></td></tr><tr><td>CRAS de referência</td><td> </td><td></td><td></td></tr><tr><td>CREAS</td><td> </td><td></td><td></td></tr><tr><td>Unidade básica de saúde</td><td> </td><td></td><td></td></tr><tr><td>CAPS infantojuvenil</td><td> </td><td></td><td></td></tr><tr><td>Secretaria de Educação (setor responsável)</td><td> </td><td></td><td></td></tr><tr><td>Delegacia</td><td> </td><td></td><td></td></tr><tr><td>Ministério Público</td><td> </td><td></td><td></td></tr><tr><td>Referências da escola para proteção</td><td> </td><td></td><td></td></tr></tbody></table></div><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Telefones nacionais</th><th>Número</th><th>Quando usar</th></tr></thead><tbody><tr><td>Disque Direitos Humanos</td><td>100</td><td>Denúncia de violação de direitos, inclusive anônima. Todos os dias, 24 horas.</td></tr><tr><td>Polícia Militar</td><td>190</td><td>Risco imediato à vida ou crime em andamento.</td></tr><tr><td>SAMU</td><td>192</td><td>Emergência de saúde.</td></tr><tr><td>Centro de Valorização da Vida</td><td>188</td><td>Apoio emocional, a qualquer hora.</td></tr><tr><td>Central de Atendimento à Mulher</td><td>180</td><td>Violência contra a mulher, inclusive mães e responsáveis de alunos.</td></tr></tbody></table></div><h3>O que levar deste guia</h3><ul class=\"chk\"><li><span></span>Percebo sinais e registro fatos, sem tirar conclusões.</li><li><span></span>Acolho o relato, acredito e não faço perguntas.</li><li><span></span>Não prometo segredo.</li><li><span></span>Comunico à direção no mesmo dia.</li><li><span></span>Mantenho o sigilo e a rotina do aluno.</li><li><span></span>Interrompo o bullying na hora e acompanho por semanas.</li><li><span></span>Trabalho a prevenção com a turma durante todo o ano.</li><li><span></span>Cuido de mim e divido o peso com a equipe.</li></ul>"},{"id":"c32","titulo":"Glossário","html":"<dl><dt>Aliciamento</dt><dd>Processo em que um adulto ganha a confiança de uma criança para abusar dela.</dd><dt>Autolesão</dt><dd>Ato de machucar o próprio corpo, em geral como forma de lidar com um sofrimento.</dd><dt>Bullying</dt><dd>Intimidação repetida e intencional, com desequilíbrio de poder entre quem agride e quem sofre.</dd><dt>Conselho Tutelar</dt><dd>Órgão que zela pelos direitos de crianças e adolescentes e recebe as comunicações da escola.</dd><dt>Cyberbullying</dt><dd>Bullying praticado por meios digitais.</dd><dt>Depoimento especial</dt><dd>Oitiva da criança perante a polícia ou a Justiça, com profissional especializado.</dd><dt>Escuta especializada</dt><dd>Entrevista feita por profissional da rede de proteção, limitada ao necessário.</dd><dt>Exploração sexual</dt><dd>Uso de criança ou adolescente em atividade sexual em troca de dinheiro, presente ou favor.</dd><dt>Medida de proteção</dt><dd>Decisão que garante direitos da criança, aplicada pelo Conselho Tutelar ou pela Justiça.</dd><dt>Negligência</dt><dd>Omissão de cuidados básicos por quem tem condições de cuidar.</dd><dt>Prática restaurativa</dt><dd>Forma de tratar conflitos que busca reparar o dano e refazer a convivência.</dd><dt>Rede de proteção</dt><dd>Conjunto de serviços de educação, saúde, assistência, segurança e justiça que protegem a criança.</dd><dt>Revelação espontânea</dt><dd>Relato feito pela criança por iniciativa própria a um adulto de confiança.</dd><dt>Revitimização</dt><dd>Novo sofrimento causado à vítima por perguntas repetidas, exposição ou descrédito.</dd></dl>"}];

/** Avaliação final do livro. O gabarito só é usado no servidor. */
export const avaliacao: QuestaoDaAvaliacao[] = [{"pergunta":"Para comunicar uma suspeita de violência contra um aluno, o servidor precisa de:","alternativas":["Suspeita fundada em sinais ou em um relato.","Autorização da família.","Confissão do agressor.","Prova."],"correta":0,"explicacao":"A lei pede comunicação diante da suspeita."},{"pergunta":"Quando o aluno pede segredo ao contar uma violência, o professor:","alternativas":["Encerra a conversa.","Chama a turma.","Promete segredo.","Explica que precisa contar a quem pode protegê-lo."],"correta":3,"explicacao":"O dever de proteger vem antes do segredo."},{"pergunta":"Ao ouvir o relato de um aluno, o professor deve:","alternativas":["Chamar o suspeito.","Pedir que repita a outros servidores.","Pedir todos os detalhes.","Acolher, acreditar e não fazer perguntas para obter detalhes."],"correta":3,"explicacao":"Quem ouve em detalhe é profissional preparado."},{"pergunta":"O registro escrito deve conter:","alternativas":["Opiniões sobre a família.","Fatos, datas e as palavras do aluno.","O diagnóstico do caso.","Fotos do corpo do aluno."],"correta":1,"explicacao":"Fatos, e não interpretações."},{"pergunta":"Quando a suspeita envolve alguém da casa do aluno, a direção:","alternativas":["Resolve internamente.","Chama a família primeiro.","Comunica primeiro ao Conselho Tutelar.","Espera novos sinais."],"correta":2,"explicacao":"Avisar a casa pode colocar a criança em risco."},{"pergunta":"Diante de sinais de autolesão, o professor:","alternativas":["Pede para ver as marcas.","Conversa em particular, acolhe e avisa a direção no mesmo momento.","Comenta com a turma.","Espera passar."],"correta":1,"explicacao":"Os sinais são levados a sério sempre."},{"pergunta":"O que diferencia o bullying de uma briga isolada?","alternativas":["Repetição, intenção e desequilíbrio de poder.","O local.","O número de testemunhas.","A idade dos alunos."],"correta":0,"explicacao":"São os três elementos da intimidação sistemática."},{"pergunta":"No bullying, colocar alvo e autor frente a frente para fazerem as pazes é:","alternativas":["Suficiente para encerrar o caso.","O primeiro passo.","Não recomendado, pois pode intimidar ainda mais a vítima.","Obrigatório."],"correta":2,"explicacao":"As conversas são feitas em separado."}];
